manifest_content:
[workspace]
resolver = "3"
members = [
    # ─── OSS crates ─────────────────────────────────────────────────────────
    "auth",
    "compress",
    "config",
    "secrets",
    "observability",
    "pricing",
    "savings",
    "runtime",
    "react-agent",
    "orchestrator",
    "types",
    "utils",
    "server",
    "coding-policy",
    "oci",
    "flow",
    "hitl",
    "agent-proxy",
    "llm-router",
    "tool-compact",
    "mcp-gateway",
    "cli",
    "github",
    "bench",
    "bench-support",
]

[workspace.package]
edition = "2024"
version = "0.1.0"

[workspace.dependencies]
# ─── Internal OSS crates ────────────────────────────────────────────────────
nasiko-auth = { path = "auth" }
nasiko-compress = { path = "compress" }
nasiko-config = { path = "config" }
nasiko-pricing = { path = "pricing" }
nasiko-savings = { path = "savings" }
nasiko-flow = { path = "flow" }
nasiko-hitl = { path = "hitl" }
nasiko-agent-proxy = { path = "agent-proxy" }
nasiko-mcp-gateway = { path = "mcp-gateway" }
nasiko-github = { path = "github" }
nasiko-secrets = { path = "secrets" }
nasiko-observability = { path = "observability" }
nasiko-runtime = { path = "runtime", default-features = false }
nasiko-react-agent = { path = "react-agent" }
nasiko-orchestrator = { path = "orchestrator" }
nasiko-types = { path = "types" }
nasiko-utils = { path = "utils" }
nasiko-server = { path = "server" }
nasiko-coding-policy = { path = "coding-policy" }
nasiko-oci = { path = "oci" }
nasiko-llm-router = { path = "llm-router" }
nasiko-tool-compact = { path = "tool-compact" }
nasiko-bench-support = { path = "bench-support" }

# ─── Testing ────────────────────────────────────────────────────────────────
serial_test = "3"

# ─── Async runtime & web ────────────────────────────────────────────────────
tokio = { version = "1", features = ["full"] }
axum = { version = "0.8", features = ["json", "query", "multipart"] }
tower = "0.5"
tower-http = { version = "0.6", features = ["cors", "trace", "decompression-zstd"] }

# ─── OpenAPI docs ───────────────────────────────────────────────────────────
utoipa = { version = "5", features = ["axum_extras", "uuid", "chrono"] }
utoipa-swagger-ui = { version = "9", features = ["axum"] }

# ─── Serialization ──────────────────────────────────────────────────────────
serde = { version = "1", features = ["derive"] }
# `raw_value`: the agent state API stores and returns JSON bodies byte for byte, never re-encoded.
serde_json = { version = "1", features = ["raw_value"] }

# ─── Text / patterns ────────────────────────────────────────────────────────
regex = "1"

# ─── Database & state ───────────────────────────────────────────────────────
sqlx = { version = "0.8", features = ["runtime-tokio", "postgres", "chrono", "uuid", "rust_decimal", "migrate", "json", "tls-rustls"] }
redis = { version = "0.27", features = ["tokio-comp", "aio", "tokio-rustls-comp", "tls-rustls-webpki-roots"] }
rust_decimal = { version = "1.36", features = ["serde", "db-postgres"] }

# ─── Auth ───────────────────────────────────────────────────────────────────
jsonwebtoken = "9"
bcrypt = "0.15"

# ─── HTTP client ────────────────────────────────────────────────────────────
reqwest = { version = "0.12", default-features = false, features = ["json", "rustls-tls", "stream"] }
rustls = { version = "0.23", features = ["ring"] }

# ─── LLM orchestration ──────────────────────────────────────────────────────
# Exact-pinned, not a "0.11" caret range: the orchestrator's HITL pause detection
# (oss/react-agent) recovers a tool error through rig's type-erasure boxing, verified
# against this exact version's `ToolSetError`/`ToolError::ToolCallError` shape
# (rig-core-0.11.1/src/tool.rs). A `cargo update` under a caret range could silently
# move that boxing behavior without anything here noticing.
rig-core = { version = "=0.11.1", default-features = false, features = ["derive"] }

# ─── CLI ────────────────────────────────────────────────────────────────────
toml_edit = "0.25"
clap = { version = "4", features = ["derive"] }
ureq = { version = "3", features = ["json"] }
dialoguer = "0.11"
indicatif = "0.17"
dirs = "6"
tar = "0.4"
flate2 = "1"
which = "7"
include_dir = "0.7"
ratatui = "0.29"
crossterm = "0.29"
tabled = "0.21"
# Already pulled in transitively via console (dialoguer's dep) at this exact version; declared
# directly here only for `oss/cli`'s own scoped SIGINT no-op guard (hitl.rs) — see its doc
# comment for why dialoguer/console's own Ctrl+C handling can't be used for this instead.
libc = "0.2"
# Read-only access to coding agents' local history stores (OpenCode's opencode.db, Cursor's
# state.vscdb) for `nasiko agents setup/import`. Pinned to 0.32 because it links the same
# libsqlite3-sys (0.30) that sqlx's optional sqlite driver already puts in the lockfile — two
# crates may not both link `sqlite3`.
rusqlite = { version = "0.32", features = ["bundled"] }

# ─── Observability ──────────────────────────────────────────────────────────
t
